"""moth-jev-adapters: mock-first clients with a real-client seam.

Directive (research/2026-09-23-moth-fleet/DIRECTIVE.md): MOTH endpoint NOT
yet discovered (~40 probes failed; docs live in Casey's onboarding mail).
JEV_API_KEY exists but no public endpoint resolves either. So: adapters
route to real HTTP only when MOTH_BASE_URL / JEV_BASE_URL is set; until
then every call returns a typed REFUSAL row — an endpoint you cannot
reach is an honest refusal, receipted, never a fabricated success.
Secrets are sourced, never printed.
"""
from __future__ import annotations

import hashlib
import json
import os
import urllib.request
from pathlib import Path


def _load_secret(name: str) -> str | None:
    for p in (Path("/root/.openclaw/secrets") / f"{name.lower()}.env",
              Path.home() / ".openclaw" / "secrets" / f"{name.lower()}.env"):
        if p.exists():
            for line in p.read_text().splitlines():
                if line.startswith("export "):
                    k, _, v = line[7:].partition("=")
                    if k.strip() == name:
                        return v.strip().strip('"').strip("'")
    return os.environ.get(name)


def _post(url: str, key: str, payload: dict, timeout: int = 20) -> dict:
    req = urllib.request.Request(
        url, data=json.dumps(payload).encode(),
        headers={"Authorization": f"Bearer {key}",
                 "Content-Type": "application/json"})
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        return json.loads(resp.read())


def refusal(tool: str, reason: str, detail: str) -> dict:
    return {"kind": "REFUSAL/v1", "producer": {"tool": tool, "version": "0.1"},
            "occurred_at": "receipt-time", "reason": reason, "detail": detail,
            "refusal_hash": hashlib.sha256(
                f"{tool}:{reason}:{detail}".encode()).hexdigest()[:16]}


class MothClient:
    """Autonomous vulnerability hunter. Mock-first: real seam = MOTH_BASE_URL."""

    def __init__(self, base_url: str | None = None):
        self.base_url = base_url or os.environ.get("MOTH_BASE_URL")
        self.key = _load_secret("MOTH_API_KEY")

    def hunt(self, repo: str, surface: str = "auto") -> dict:
        if not self.base_url:
            return refusal("moth-adapter", "ENDPOINT_UNKNOWN",
                           f"hunt({repo},{surface}) queued as mock; set MOTH_BASE_URL to go live")
        if not self.key:
            return refusal("moth-adapter", "KEY_MISSING", "MOTH_API_KEY not in secrets/")
        return _post(f"{self.base_url}/v1/hunt", self.key,
                     {"repo": repo, "surface": surface})

    def findings(self, hunt_id: str) -> dict:
        if not self.base_url:
            return refusal("moth-adapter", "ENDPOINT_UNKNOWN", f"findings({hunt_id})")
        return _post(f"{self.base_url}/v1/findings", self.key, {"hunt_id": hunt_id})


class JevClient:
    """ℚ16 evolution / cellular substrate. Real seam = JEV_BASE_URL."""

    def __init__(self, base_url: str | None = None):
        self.base_url = base_url or os.environ.get("JEV_BASE_URL")
        self.key = _load_secret("JEV_API_KEY")

    def evolve(self, genome: dict, ticks: int) -> dict:
        if not self.base_url:
            return refusal("jev-adapter", "ENDPOINT_UNKNOWN",
                           f"evolve(ticks={ticks}) mock; set JEV_BASE_URL to go live")
        if not self.key:
            return refusal("moth-adapter", "KEY_MISSING", "JEV_API_KEY not in secrets/")
        return _post(f"{self.base_url}/v1/evolve", self.key,
                     {"genome": genome, "ticks": ticks})


if __name__ == "__main__":
    demo = [MothClient().hunt("SuperInstance/quilt-studio"),
            JevClient().evolve({"seed": 4}, 100)]
    for row in demo:
